from decimal import Decimal, ROUND_HALF_UP
from typing import Any


_CENT = Decimal("0.01")


def _numeric(value: Any) -> Decimal:
    """Return the legacy numeric value, with empty or missing values as zero."""
    if value is None:
        return Decimal("0")
    if isinstance(value, str):
        if not value.strip():
            return Decimal("0")
        return Decimal(value.strip())
    return Decimal(str(value))


def _amount(value: Any) -> Decimal:
    """Coerce a currency amount using legacy half-up rounding to cents."""
    return _numeric(value).quantize(_CENT, rounding=ROUND_HALF_UP)


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    eligible = [
        (index, account)
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]

    eligible.sort(key=lambda item: item[1].get("ACCT_ID"))

    for index, account in eligible:
        acct_id = account.get("ACCT_ID")

        exposure = Decimal("0")
        if acct_id is not None:
            for order in orders:
                if (
                    order.get("ACCT_ID") == acct_id
                    and order.get("DEL_FLG") != "Y"
                    and order.get("STAT_CD") == "I"
                ):
                    exposure += _amount(order.get("TOT_AMT"))

        credit_limit = _amount(account.get("CRED_LIMIT"))
        updated = new_accounts[index]

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            updated["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= credit_limit * Decimal("8") / Decimal("10"):
            current_hold = updated.get("CRED_HOLD", account.get("CRED_HOLD"))
            if current_hold == "Y":
                updated["CRED_HOLD"] = "N"
                audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
